sp_widget.css:
/* ==========================================
   CARD
========================================== */

.tm-card{
    background:#FFFFFF;
    border:1px solid #E5E7EB;
    border-radius:18px;
    padding:20px;
    box-shadow:0 4px 18px rgba(15,23,42,.06);
}

/* ==========================================
   HEADER
========================================== */

.tm-card-head{
    display:flex;
    justify-content:space-between;
    align-items:center;
    margin-bottom:18px;
}

.tm-card-title{
    margin:0;
    font-size:18px;
    font-weight:700;
    color:#0F172A;
}

.tm-link{
    text-decoration:none;
    color:#2563EB;
    font-size:13px;
    font-weight:600;
}

.tm-link:hover{
    color:#1D4ED8;
    text-decoration:none;
}

/* ==========================================
   TABLE
========================================== */

.tm-table{
    width:100%;
    border-collapse:collapse;
}

.tm-table thead{
    background:#F8FAFC;
}

.tm-table th{
    padding:12px;
    font-size:12px;
    font-weight:700;
    text-transform:uppercase;
    letter-spacing:.5px;
    color:#64748B;
    text-align:left;
}

.tm-table td{
    padding:14px 12px;
    border-top:1px solid #F1F5F9;
    color:#0F172A;
    font-size:13px;
}

/* ==========================================
   ROW HOVER
========================================== */

.tm-table tbody tr{
    transition:.2s;
}

.tm-table tbody tr:hover{
    background:#F8FAFC;
}

/* ==========================================
   PATIENT LINK
========================================== */

.tm-patient-link{
    text-decoration:none;
    color:#0F172A;
    font-weight:600;
}

.tm-patient-link:hover{
    color:#2563EB;
}

/* ==========================================
   COUNT BADGES
========================================== */

.tm-count{
    display:inline-flex;
    align-items:center;
    justify-content:center;
    min-width:34px;
    padding:4px 8px;
    border-radius:999px;
    font-size:12px;
    font-weight:700;
}

.taken-count{
    background:#ECFDF5;
    color:#16A34A;
}

.missed-count{
    background:#FEF2F2;
    color:#DC2626;
}

/* ==========================================
   ADHERENCE PILLS
========================================== */

.tm-pill{
    display:inline-flex;
    align-items:center;
    justify-content:center;
    min-width:70px;
    padding:5px 12px;
    border-radius:999px;
    font-size:12px;
    font-weight:700;
}

.taken{
    background:#ECFDF5;
    color:#16A34A;
    border:1px solid #BBF7D0;
}

.pending{
    background:#FFFBEB;
    color:#D97706;
    border:1px solid #FCD34D;
}

.missed{
    background:#FEF2F2;
    color:#DC2626;
    border:1px solid #FECACA;
}

/* ==========================================
   EMPTY STATE
========================================== */

.tm-empty{
    text-align:center;
    color:#64748B;
    padding:25px !important;
}

/* ==========================================
   RESPONSIVE
========================================== */

@media(max-width:768px){

    .tm-card{
        overflow-x:auto;
    }

    .tm-table{
        min-width:700px;
    }
}

sp_widget.script:
(function() {
    data.rows = [];

    // MANUALLY ADD FAKE DATA HERE
    // Format: { name: "Patient Name", scheduled: X, taken: X, missed: X, adherence: X }

    var fakePatients = [
        { name: "Nagayya", scheduled: 28, taken: 28, missed: 0, adherence: 100 },
        { name: "Aarav Sharma", scheduled: 30, taken: 28, missed: 2, adherence: 93 },
        { name: "Abhishek", scheduled: 25, taken: 22, missed: 3, adherence: 88 },
        { name: "Kajal_az", scheduled: 31, taken: 29, missed: 2, adherence: 94 },

    ];

    // Process the fake data
    for (var i = 0; i < fakePatients.length; i++) {
        var fp = fakePatients[i];

        data.rows.push({
            name: fp.name,
            scheduled: fp.scheduled,
            taken: fp.taken,
            missed: fp.missed,
            pct: fp.adherence  // adherence percentage
        });
    }

    // Sort by adherence percentage (lowest to highest)
    data.rows.sort(function(a, b) {
        return a.pct - b.pct;
    });
})();
